from typing import Any

from ourob.skills.base import Skill, SkillContext, skill
from ourob.state.model import SkillResult


@skill(
    "word_count",
    title="Word count",
    description="Count whitespace-delimited words in a string.",
    params={"text": {"type": "str", "required": True, "desc": "input text"}},
)
class WordCount(Skill):
    """Count whitespace-delimited words."""

    def run(self, ctx: SkillContext, **kwargs: Any) -> SkillResult:
        text = str(kwargs["text"])
        count = len(text.split())
        return SkillResult(ok=True, output=str(count), data={"count": count})

